import{_ as e,o as t,c as s,ag as i}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-10-30（材料 / 半导体光伏 · 伪直接带隙）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/science-daily-2026-10-30-materials.md","filePath":"topics/materials/science-daily-2026-10-30-materials.md"}'),a={name:"topics/materials/science-daily-2026-10-30-materials.md"};function r(c,o,n,l,d,g){return t(),s("div",null,[...o[0]||(o[0]=[i('<h1 id="科学日报-·-2026-10-30-材料-半导体光伏-·-伪直接带隙" tabindex="-1">科学日报 · 2026-10-30（材料 / 半导体光伏 · 伪直接带隙） <a class="header-anchor" href="#科学日报-·-2026-10-30-材料-半导体光伏-·-伪直接带隙" aria-label="Permalink to &quot;科学日报 · 2026-10-30（材料 / 半导体光伏 · 伪直接带隙）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-30.md</code> — 第49期 ｜ 科学板块（1 篇） 落盘说明：文件名带 <code>-materials</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-30-材料-·-1-1-硫化铋的「伪直接带隙」——强吸收却延迟复合-绕开基尔霍夫互易原理" tabindex="-1">科学日报 2026-10-30（材料 · 1/1）：硫化铋的「伪直接带隙」——强吸收却延迟复合，绕开基尔霍夫互易原理 <a class="header-anchor" href="#科学日报-2026-10-30-材料-·-1-1-硫化铋的「伪直接带隙」——强吸收却延迟复合-绕开基尔霍夫互易原理" aria-label="Permalink to &quot;科学日报 2026-10-30（材料 · 1/1）：硫化铋的「伪直接带隙」——强吸收却延迟复合，绕开基尔霍夫互易原理&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-30.md</code> ｜ DOI: 10.1038/s41586-026-11223-x ｜ Nature (2026)</p></blockquote><ul><li>问题：1860 年<strong>基尔霍夫</strong>证明<strong>吸收率与发射率互为倒数</strong>（好吸收体必是好发射体）；这条互易原理经广义普朗克定律落到半导体上，就是 <strong>van Roosbroeck–Shockley 方程</strong>——它给<strong>太阳能转换</strong>设了硬上限：想强吸收光，就必然强辐射复合。</li><li>方法：作者在<strong>硫化铋（Bi₂S₃）<strong>中测定其带隙性质——一种「<strong>伪直接带隙（pseudo-direct bandgap）</strong>」：<strong>一个能量更低的间接跃迁</strong>，搭配</strong>一个高出仅几个 k_BT 的直接跃迁</strong>（两能级靠得很近，但一个是间接、一个是直接）。</li><li>结果（实测）： <ul><li>伪直接带隙特征<strong>显著抑制双分子（bimolecular）电子—空穴复合</strong>——相对经典直接带隙半导体；</li><li>因而<strong>在保持高吸收系数的同时延迟复合</strong>，为<strong>突破普朗克定律限制</strong>提供前所未有的可能。</li></ul></li><li>洞察（对本库 <code>materials</code> × <code>physics</code>）： <ol><li><strong>「把两个本该一致的性质解耦」＝绕开热力学互易的路径</strong> —— 基尔霍夫互易说「吸收强 ⟹ 发射强」，而<strong>伪直接带隙用「间接低能态 + 近邻直接态」的双能级结构，让吸收走直接态、复合被迫走间接态</strong>，使二者不再绑定。判据：<strong>当一个系统的两条性质被一条互易/守恒律锁死时，先问「能否用一个近简并的中间态，让好性质与坏性质分别走不同的通道」。</strong> 这与本库 10-25 钙钛矿「解耦 SAM 锚定与结晶」、10-29 硅酮「就地造只认这条键的中间体」同族——<strong>改路径/换通道优于加力度。</strong></li><li><strong>「光伏的下一代效率不一定靠新材料，而靠新的带隙工程」</strong> —— 硫化铋是成熟、廉价、无毒的半导体；关键创新是<strong>识别出它的伪直接带隙这一此前未被利用的性质</strong>。可迁移判据：<strong>当一个成熟材料的下限来自一条物理律，先检查它是否具备某种「近简并 + 通道分离」的结构，而不是急着换新材料。</strong></li><li><strong>一句话定位</strong>：这是对「<strong>吸收—发射互易是光伏天花板</strong>」这一共识的一次机制性绕行，把 <code>materials</code> 的光伏主线从「钙钛矿/叠层」扩到「<strong>伪直接带隙半导体</strong>」这一类。</li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/materials/index.md</code> ｜ <code>topics/physics/index.md</code> ｜ 第49期 科学板块</p></blockquote><p>关键词：科学日报第49期、硫化铋 Bi2S3、伪直接带隙 pseudo-direct bandgap、间接跃迁、直接跃迁、k_BT、双分子复合 bimolecular recombination、延迟电子空穴复合、吸收系数、基尔霍夫互易原理、广义普朗克定律、van Roosbroeck-Shockley 方程、太阳能转换、光伏效率上限、能级近简并、通道分离、解耦耦合过程、换路径优于加力度</p><p>关联：<code>topics/materials/index.md</code>、<code>topics/materials/science-daily-2026-10-29-materials.md</code>（碳戊搭烯纳米带 / 硅酮解聚）、<code>topics/physics/index.md</code>、<code>topics/quantum-physics/science-daily-2026-10-30-quantum.md</code>、<code>topics/ai-brain/index.md</code></p>',10)])])}const u=e(a,[["render",r]]);export{m as __pageData,u as default};
